subsection.content:
En langage C :

type identificateur (paramètres)

{

  // instructions

  return expression ;

}

subsubsection.content:
Algorithme :

ALGORITHME rechmax ;

VAR x, y, grand : Entier ;

FONCTION Max(a, b : Entier) : Entier ;

DÉBUT

  SI (a >= b) ALORS Max <- a ; SINON Max <- b ;

FIN ;

DÉBUT

  LIRE(x, y) ;

  grand <- Max(x, y) ;

  ÉCRIRE("La plus grande valeur entre ", x, " et ", y, " est : ", grand) ;

FIN.

Algorithme avec fonction factorielle :

ALGORITHME combinaison ;

VAR n, p : Entier ;

FONCTION Fact(x : Entier) : Entier ;

VAR i, r : Entier ;

DÉBUT

  r <- 1 ;

  POUR i ALLANT DE 2 À x FAIRE

    r <- r * i ;

  FIN POUR ;

  Fact <- r ;

FIN ;

DÉBUT

  ÉCRIRE("Valeurs de n et p ? ") ;

  LIRE(n, p) ;

  ÉCRIRE("Résultat = ", Fact(n) DIV (Fact(p) * Fact(n-p))) ;

FIN.

Algorithme :

ALGORITHME rechmaxPro ;

VAR x, y, grand : Entier ;

PROCÉDURE Max(E a, b : Entier ; S M : Entier) ;

DÉBUT

  SI (a >= b) ALORS

    M <- a ;

  SINON

    M <- b ;

  FIN ;

DÉBUT

  LIRE(x, y) ;

  Max(x, y, grand) ;

  ÉCRIRE("La plus grande valeur entre ", x, " et ", y, " est : ", grand) ;

FIN.

Algorithme :

ALGORITHME permutation ;

VAR a, b : Entier ;

PROCÉDURE echanger(E/S x, y : Entier) ;

VAR temp : Entier ;

DÉBUT

  temp <- x ;

  x <- y ;

  y <- temp ;

FIN ;

DÉBUT

  ÉCRIRE("Entrez deux entiers : ") ;

  LIRE(a, b) ;

  echanger(a, b) ;

  ÉCRIRE("a = ", a, " et b = ", b) ;

FIN.
